// ========================================
// 1. ENTRADAS
// ========================================

const items = $input.all();

// ========================================
// 2. CONFIGURAÇÕES
// ========================================

const relationNames = [
  '✅ Tarefas Relacionadas',
  'Subitem'
];

const visited = new Set();
const tasks = [];

// ========================================
// 3. FUNÇÃO RECURSIVA
// ========================================

function flattenTask(task, parentId = null, level = 0) {

  if (!task || typeof task !== 'object' || !task.id) {
    return;
  }

  // Evitar duplicações e referências circulares
  if (visited.has(task.id)) {
    return;
  }

  visited.add(task.id);

  // Extrair relações expandidas
  const children = [];

  for (const relationName of relationNames) {
    const related = task[relationName];

    if (Array.isArray(related)) {
      children.push(...related);
    }
  }

  // Remover estruturas recursivas
  const flattenedTask = { ...task };

  for (const relationName of relationNames) {
    delete flattenedTask[relationName];
  }

  // Informações da hierarquia
  flattenedTask.parentId = parentId;
  flattenedTask.level = level;

  tasks.push(flattenedTask);

  // Percorrer filhos recursivamente
  for (const child of children) {
    flattenTask(child, task.id, level + 1);
  }
}

// ========================================
// 4. PROCESSAMENTO
// ========================================

for (const item of items) {

  const data = item.json;
  const roots = Array.isArray(data) ? data : [data];

  for (const root of roots) {

    // Ignorar a tarefa original
    // Processar apenas suas relações expandidas
    for (const relationName of relationNames) {

      const related = root[relationName];

      if (!Array.isArray(related)) {
        continue;
      }

      for (const task of related) {
        flattenTask(task);
      }
    }
  }
}

// ========================================
// 5. SAÍDA
// ========================================

return tasks.map(task => ({
  json: task
}));

// ========================================
// 1. ENTRADAS
// ========================================

const items = $('Percorrer modelos para duplicação').all();

const taxonomiasModelo = $('Buscar taxonomia de modelos de tarefa')
  .first().json.results ?? [];

/*const parent = $('When Executed by Another Workflow')
  .first().json.parent;*/

// ========================================
// 2. CONFIGURAÇÕES
// ========================================

const ignoredTypes = new Set([
  'formula',
  'rollup',
  'created_time',
  'created_by',
  'last_edited_time',
  'last_edited_by',
  'unique_id',
  'button',
  'verification'
]);

const ignoredProperties = new Set([
  'Subitem',
  'Item pai',
  'Bloqueando',
  'Bloqueada por'
]);

const taxonomiasModeloIds = new Set(
  taxonomiasModelo.map(item => item.id)
);

// ========================================
// 3. PROCESSAMENTO
// ========================================

return items.map(item => {

  const tarefa = item.json;

  if (!tarefa?.properties) {
    throw new Error('Propriedades da tarefa não encontradas.');
  }

  const properties = {};

  for (const [name, property] of Object.entries(tarefa.properties)) {
    const type = property.type;

    if (
      ignoredTypes.has(type) ||
      ignoredProperties.has(name)
    ) {
      continue;
    }

    if (property[type] === undefined) {
      continue;
    }

    properties[name] = {
      [type]: property[type]
    };
  }

  // Limpar referências reversas
  if (properties['↩️ Referenciada por']) {
    properties['↩️ Referenciada por'].relation = [];
  }

  // Remover taxonomias do modelo
  if (properties['🏷️ Taxonomia']?.relation) {
    properties['🏷️ Taxonomia'].relation =
      properties['🏷️ Taxonomia'].relation.filter(
        relation => !taxonomiasModeloIds.has(relation.id)
      );
  }

  // Atualizar tarefa pai
  /*if (properties['Item pai']) {
    properties['Item pai'].relation = parent?.id
      ? [{ id: parent.id }]
      : [];
  }*/

  // ========================================
  // 4. SAÍDA
  // ========================================

  return {
    json: {
      properties
    }
  };

});

