// ========================================
// 1. ENTRADAS
// ========================================

// Par atual do Loop Over Items2
const atual = $input.item.json;

// Todas as tarefas duplicadas e seus modelos
const agregados = $('Reunir tarefas criadas e modelos de origem').first().json.data ?? [];

// ========================================
// 2. MAPA DE IDS
// ========================================

// ID do modelo → ID da tarefa duplicada
const idDuplicadoPorModelo = new Map();

for (const item of agregados) {
  const modeloId = item.modelo?.id;
  const tarefaId = item.tarefa?.id;

  if (!modeloId || !tarefaId) {
    throw new Error(
      'O Aggregate3 contém uma tarefa ou modelo sem ID.'
    );
  }

  if (idDuplicadoPorModelo.has(modeloId)) {
    throw new Error(
      `Modelo duplicado no Aggregate3: ${modeloId}`
    );
  }

  idDuplicadoPorModelo.set(modeloId, tarefaId);
}

// ========================================
// 3. TAREFA ATUAL
// ========================================

const tarefa = atual.tarefa;
const modelo = atual.modelo;

if (!tarefa?.id || !modelo?.id) {
  throw new Error(
    'O item atual não contém tarefa e modelo válidos.'
  );
}

const properties = {};

// ========================================
// 4. FUNÇÃO PARA CONVERTER RELAÇÕES
// ========================================

function converterRelacoes(nomePropriedade) {
  const originais =
    modelo.properties?.[nomePropriedade]?.relation ?? [];

  const duplicadas = [];

  for (const original of originais) {
    const novoId = idDuplicadoPorModelo.get(original.id);

    // Relações externas ao conjunto duplicado
    // não são reconstruídas neste processamento.
    if (!novoId) continue;

    duplicadas.push({ id: novoId });
  }

  return duplicadas;
}

// ========================================
// 5. SUBITENS
// ========================================

const subitens = converterRelacoes('Subitem');

if (subitens.length > 0) {
  properties['Subitem'] = {
    relation: subitens
  };
}

// ========================================
// 6. DEPENDÊNCIAS
// ========================================

const bloqueando = converterRelacoes('Bloqueando');

if (bloqueando.length > 0) {
  properties['Bloqueando'] = {
    relation: bloqueando
  };
}

// ========================================
// 7. TAREFAS RELACIONADAS
// ========================================

const relacionadas = converterRelacoes(
  '✅ Tarefas Relacionadas'
);

if (relacionadas.length > 0) {
  properties['✅ Tarefas Relacionadas'] = {
    relation: relacionadas
  };
}

// ========================================
// 8. SAÍDA
// ========================================

return {
  json: {
    id_tarefa: tarefa.id,
    properties,
    atualizar: Object.keys(properties).length > 0
  }
};

