 // ========================================
 // 1. ENTRADAS
 // ========================================

const item = $input.first().json;

 // Participante atual do loop
 const participante = item.participante;

 // Tarefa original, fora do loop
 const tarefa = item.tarefa;

 // ========================================
 // 2. FUNÇÕES EXIGIDAS PELA TAREFA
 // ========================================

 const funcoesTarefa = new Set(
   (tarefa['🏷️ Taxonomia'] ?? [])
     .filter(taxonomia =>
       taxonomia.properties?.Natureza?.select?.name === 'Função'
     )
     .map(taxonomia => taxonomia.id)
 );

 // ========================================
 // 3. VALIDAR PARTICIPANTE
 // ========================================

 const taxonomiasParticipante =
   participante['🏷️ Taxonomia'] ?? [];

 const taxonomiaCorreta =
   funcoesTarefa.size > 0 &&
   taxonomiasParticipante.some(taxonomia =>
     taxonomia.properties?.Natureza?.select?.name === 'Função' &&
     funcoesTarefa.has(taxonomia.id)
   );

 // ========================================
 // 4. SAÍDA
 // ========================================

 return {
   json: {
     participante,
     taxonomiaCorreta
   }
 };

